/// Apply caller-selected UTF-8 byte edits atomically using the shared renderer.
/// Invalid, overlapping, ambiguous or non-character-boundary edits fail without
/// output. A successful result does not claim a syntax check or AST selection.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn smc_apply_explicit_source_edits(
    request: AlefHandle,
    limits: AlefHandle,
) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [
            Some(HandleRequest {
                handle: request,
                expected_type: std::any::TypeId::of::<structuredmerge_core::SourceEditRequest>(),
            }),
            Some(HandleRequest {
                handle: limits,
                expected_type: std::any::TypeId::of::<structuredmerge_core::SourceEditLimits>(),
            }),
        ]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if request == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'request'",
            );
            return 0;
        }
        let request_rs_ptr = match locked_handle_ptr::<structuredmerge_core::SourceEditRequest>(
            &mut __alef_guards,
            request,
        ) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let request_rs = unsafe { &*request_rs_ptr }.clone();

        if limits == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'limits'",
            );
            return 0;
        }
        let limits_rs_ptr = match locked_handle_ptr::<structuredmerge_core::SourceEditLimits>(
            &mut __alef_guards,
            limits,
        ) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let limits_rs = unsafe { &*limits_rs_ptr }.clone();

        let result = structuredmerge_core::apply_explicit_source_edits(request_rs, limits_rs);
        match result {
            Ok(val) => match insert_handle(val) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(e) => {
                set_last_error_from(&e, &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

