/// with `smc_native_merge_profiles`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn smc_native_merge_profiles_len() -> usize {
    catch_ffi_panic_preserving_error(0, || last_return_len("smc_native_merge_profiles"))
}

